import{t as e}from"./client-B9FPHoAU.js";var t={list(t){return e.get(`/directives`,{params:t}).then(e=>e.data)},create(t){return e.post(`/directives`,t).then(e=>e.data)},remove(t){return e.delete(`/directives/${t}`).then(e=>e.data)},review(t,n){return e.put(`/directives/${t}/review`,n).then(e=>e.data)},download(t){return e.get(`/directives/${t}/download`,{responseType:`blob`})},downloadReply(t){return e.get(`/directives/${t}/download-reply`,{responseType:`blob`})},listTypes(){return e.get(`/directives/types`).then(e=>e.data)},createType(t){return e.post(`/directives/types`,{name:t}).then(e=>e.data)},deleteType(t){return e.delete(`/directives/types/${t}`).then(e=>e.data)}};export{t};